text:
{
 "questions": [
  {
   "question": "영어판에서 글 본문은 어떻게 할까요?",
   "header": "본문",
   "multiSelect": false,
   "options": [
    {
     "label": "번역 파일을 따로 (추천)",
     "description": "글마다 content/posts/<id>.en.md를 두고, 있으면 영어판에 그 번역이 나옵니다. 번역은 내가 쓰거나 Claude가 초안을 쓰고 내가 확인합니다. 빌드는 번역 서비스를 부르지 않습니다."
    },
    {
     "label": "화면 글자만 영어",
     "description": "메뉴와 안내만 영어이고 글은 한국어 그대로 보여줍니다. 가장 작은 변경입니다."
    }
   ]
  },
  {
   "question": "번역이 없는 글은 영어판에서 어떻게 보일까요?",
   "header": "번역 없음",
   "multiSelect": false,
   "options": [
    {
     "label": "한국어 원문 + 표시 (추천)",
     "description": "영어판 피드에도 모든 글이 나오고, 번역이 없는 글은 한국어 원문에 'Korean only' 같은 작은 표시를 붙입니다."
    },
    {
     "label": "영어판에서 빼기",
     "description": "번역된 글만 영어판 피드에 나옵니다. 번역이 적으면 영어판이 비어 보일 수 있습니다."
    }
   ]
  },
  {
   "question": "영어판 글 페이지의 주석(링크 사유)과 패치 보기는 어떻게 할까요?",
   "header": "링크·패치",
   "multiSelect": false,
   "options": [
    {
     "label": "원문 페이지로 안내 (추천)",
     "description": "영어판은 번역 본문만 보여주고, 주석·가리키는 글·패치 이력은 '원문(한국어)에서 보기' 링크로 안내합니다. 번역에 링크 앵커나 패치를 따로 건다는 규칙이 필요 없습니다."
    },
    {
     "label": "영어판에도 그대로",
     "description": "주석 목록과 가리키는 글 목록을 영어판에도 두되 사유는 한국어 원문 그대로 보입니다. 본문 안 [n] 링크는 번역에 앵커가 없으므로 빠집니다."
    }
   ]
  },
  {
   "question": "지금 있는 글 3개(화장실 긴 글, 짧은 글 둘)와 소개의 영어 번역은?",
   "header": "번역 초안",
   "multiSelect": false,
   "options": [
    {
     "label": "Claude가 초안 (추천)",
     "description": "기능을 만든 뒤 네 개의 번역 초안 파일을 제가 쓰고, 보여 드린 뒤 확인받고 올립니다. 글쓰기는 run 밖 절차입니다."
    },
    {
     "label": "내가 직접",
     "description": "기능만 만들고 번역은 직접 씁니다."
    },
    {
     "label": "나중에",
     "description": "이번엔 기능만 넣고 번역은 천천히."
    }
   ]
  }
 ]
}
